window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ad8535477782c40f"]={"versions": [{"id": "FIG-ad8535477782c40f", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Komponentendiagramm mit Schnittstellen- und Realisierungsbeziehungen, annotiert mit Stereotypen des AUTOSAR Adaptive Platform (AAP) Profils.\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP Release R23-11), Funktionsbereich <em>Intrusion Detection System</em> (IDS).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der standardisierten Schnittstelle zur Meldung sicherheitsrelevanter Ereignisse (Security Events) von einer Anwendung an den zentralen <em>Intrusion Detection System Manager</em> (IdsM). Das Muster realisiert eine lose Kopplung zwischen Event-Detektoren (Sensoren) und der zentralen Sicherheits-Überwachungsinstanz.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Adaptive Application</code></strong> (UML-Komponente):\n<ul class=\"fig-list\"><li>Repräsentiert einen Prozess im User-Space der Adaptive Platform, der als Security-Event-Sensor fungiert (z. B. Diagnose, Firewall, Routing-Engine).\n</li></ul>\n</li><li><strong><code>«aapPortInterface,aapAPI» EventReporter</code></strong> (UML-Interface):\n<ul class=\"fig-list\"><li><strong>Stereotypen:</strong> \n<ul class=\"fig-list\"><li><code>«aapPortInterface»</code>: Modellierungselement im AUTOSAR-Metamodell für Port-basierte Dienstarchitekturen.\n</li><li><code>«aapAPI»</code>: Direkte Repräsentation als C++ Programmierschnittstelle (<code>ara::idsm::EventReporter</code>).\n</li></ul>\n</li><li><strong>Operationen:</strong> <code>+ ReportEvent()</code>: Öffentliche Methode zum Übermitteln von Security Events inklusive Event-ID und optionalen Kontextdaten (Payload).\n</li></ul>\n</li><li><strong><code>«aapFunctionalCluster» Intrusion Detection System Manager</code></strong> (UML-Komponente):\n<ul class=\"fig-list\"><li><strong>Stereotyp:</strong> <code>«aapFunctionalCluster»</code>: Standardisierter Kernbestandteil der Adaptive Platform Architecture.\n</li><li><strong>Realisierungsform:</strong> <code>daemon-based</code>: Läuft als eigenständiger System-Daemon/Dienstprozess auf OS-Ebene.\n</li></ul>\n</li><li><strong>Beziehungen:</strong>\n<ul class=\"fig-list\"><li><code>Adaptive Application</code> –«use»→ <code>EventReporter</code>: Abhängigkeitsbeziehung (Client-Nutzung).\n</li><li><code>Intrusion Detection System Manager</code> $\\dashrightarrow \\triangle$ <code>EventReporter</code>: Schnittstellen-Realisierung (<code>Interface Realization</code>). Der Daemon implementiert das Interface serverseitig bzw. stellt die Backend-Implementierung bereit.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Eine <code>Adaptive Application</code> registriert zur Laufzeit ein sicherheitskritisches Vorkommnis (z. B. fehlgeschlagene Authentifizierung, Integritätsverletzung, CAN/Ethernet-Frame-Anomalie).\n</li><li><strong>Synchroner API-Aufruf:</strong> Die Applikation ruft die lokale Methode <code>ReportEvent()</code> der Client-Bibliothek (<code>ara::idsm</code>) auf.\n</li><li><strong>IPC-Transport:</strong> Da der <code>Intrusion Detection System Manager</code> als <em>daemon-based</em> deklariert ist, wird das Ereignis über einen Inter-Process-Communication-Kanal (IPC, z. B. Unix Domain Sockets oder POSIX Message Queues/Shared Memory) asynchron oder non-blocking in den Adressraum des IdsM-Daemons übertragen.\n</li><li><strong>Daemon-Verarbeitung:</strong> \n<ul class=\"fig-list\"><li>Validierung und Filterung (z. B. Rate Limiting, Thresholding gegen Event-Flooding/DoS).\n</li><li>Aggregation qualifizierter Security Events (QsEv) und Weiterleitung an den IdsM-Kanal (z. B. Persistenzspeicher oder On-Board/Off-Board Reporting via IdsR an ein Vehicle Security Operations Center).\n</li></ul>\n</li><li><strong>Rückmeldung:</strong> Typischerweise Rückgabe eines <code>ara::core::Result&lt;void&gt;</code> an die aufrufende Applikation (bestätigt die Pufferung der IPC-Nachricht; kein Warten auf Off-Board-Versand).\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API- und Manifest-Vertrag:</strong>\n<ul class=\"fig-list\"><li>Entwickler einer <code>Adaptive Application</code> müssen in den ARXML-Beschreibungen (Application Design / Execution Manifest) die Service-Instanz-Abhängigkeit zum <code>EventReporter</code>-Port definieren.\n</li><li>Die Security-Event-IDs müssen mit der IdsM-Konfiguration des Gesamtfahrzeugs harmonisiert sein (IDs, Context Data Types).\n</li></ul>\n</li><li><strong>IAM / Access Control:</strong>\n<ul class=\"fig-list\"><li>Der Zugriff auf die <code>EventReporter</code>-API erfordert entsprechende Berechtigungen im Identity and Access Management (IAM), um Spoofing von Security-Events durch unprivilegierte Prozesse zu verhindern.\n</li></ul>\n</li><li><strong>Laufzeit- und Echtzeitverhalten:</strong>\n<ul class=\"fig-list\"><li><code>ReportEvent()</code> muss reentrancy- und thread-safe sein.\n</li><li>Die API ist so implementiert, dass Event-Flooding die Echtzeitpfade der anwendenden Applikation nicht blockiert; bei IPC-Pufferüberlauf greifen definierte Drop-Strategien.\n</li><li>Entwickler dürfen keine sensiblen Klartextdaten (Schlüssel, Passwörter, PII) in den Kontext-Payloads von <code>ReportEvent()</code> übermitteln.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7126de56b9fa299d", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Komponentendiagramm mit Schnittstellen- und Realisierungsbeziehungen, annotiert mit Stereotypen des AUTOSAR Adaptive Platform (AAP) Profils.\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP Release R24-11), Funktionsbereich <em>Intrusion Detection System</em> (IDS).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der standardisierten Schnittstellen zur Meldung sicherheitsrelevanter Ereignisse (<code>EventReporter</code>) sowie zur Steuerung und Abfrage des Reporting-Modus (<code>ReportingModeProvider</code>) zwischen einer <code>Adaptive Application</code> und dem zentralen <code>Intrusion Detection System Manager</code> (IdsM).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Adaptive Application</code></strong> (UML-Komponente):\n<ul class=\"fig-list\"><li>Repräsentiert einen Prozess im User-Space der Adaptive Platform, der als Security-Event-Sensor fungiert und über Ports auf die IdsM-Schnittstellen zugreift.\n</li></ul>\n</li><li><strong><code>«aapPortInterface,aapAPI» EventReporter</code></strong> (UML-Interface):\n<ul class=\"fig-list\"><li><strong>Stereotypen:</strong> <code>«aapPortInterface»</code>, <code>«aapAPI»</code> (C++ Programmierschnittstelle <code>ara::idsm::EventReporter</code>).\n</li><li><strong>Operationen:</strong> <code>+ ReportEvent()</code>: Öffentliche Methode zum Übermitteln von Security Events inklusive Event-ID und optionaler Kontextdaten.\n</li></ul>\n</li><li><strong><code>«aapAPI,aapPortInterface» ReportingModeProvider</code></strong> (UML-Interface):\n<ul class=\"fig-list\"><li><strong>Stereotypen:</strong> <code>«aapAPI»</code>, <code>«aapPortInterface»</code> (C++ Programmierschnittstelle <code>ara::idsm::ReportingModeProvider</code>).\n</li><li><strong>Operationen:</strong>\n<ul class=\"fig-list\"><li><code>+ GetReportingMode()</code>: Öffentliche Methode zur Abfrage des aktuellen Reporting-Modus des IdsM.\n</li><li><code>+ SetReportingMode()</code>: Öffentliche Methode zum Konfigurieren bzw. Umschalten des Reporting-Modus.\n</li></ul>\n</li></ul>\n</li><li><strong><code>«aapFunctionalCluster» Intrusion Detection System Manager</code></strong> (UML-Komponente):\n<ul class=\"fig-list\"><li><strong>Stereotyp:</strong> <code>«aapFunctionalCluster»</code>: Standardisierter Kernbestandteil der Adaptive Platform Architecture.\n</li><li><strong>Realisierungsform:</strong> <code>daemon-based</code>: Läuft als eigenständiger System-Daemon/Dienstprozess auf OS-Ebene.\n</li></ul>\n</li><li><strong>Beziehungen:</strong>\n<ul class=\"fig-list\"><li><code>Adaptive Application</code> –«use»→ <code>EventReporter</code>: Abhängigkeitsbeziehung (Client-Nutzung zum Melden von Events).\n</li><li><code>Adaptive Application</code> –«use»→ <code>ReportingModeProvider</code>: Abhängigkeitsbeziehung (Client-Nutzung zur Abfrage und Steuerung des Reporting-Modus).\n</li><li><code>Intrusion Detection System Manager</code> $\\dashrightarrow \\triangle$ <code>EventReporter</code>: Schnittstellen-Realisierung durch den IdsM-Daemon.\n</li><li><code>Intrusion Detection System Manager</code> $\\dashrightarrow \\triangle$ <code>ReportingModeProvider</code>: Schnittstellen-Realisierung durch den IdsM-Daemon.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialisierung &amp; Modusverwaltung:</strong>\n<ul class=\"fig-list\"><li>Eine autorisierte <code>Adaptive Application</code> kann über <code>GetReportingMode()</code> den aktuellen Überwachungszustand des IdsM abfragen bzw. mittels <code>SetReportingMode()</code> den aktiven Reporting-Modus steuern (z. B. Aktivierung/Deaktivierung bestimmter Reporting-Klassen).\n</li></ul>\n</li><li><strong>Security-Event-Trigger:</strong> Eine <code>Adaptive Application</code> erkennt zur Laufzeit ein sicherheitskritisches Ereignis.\n</li><li><strong>Synchroner API-Aufruf:</strong> Die Applikation ruft <code>ReportEvent()</code> der Client-Bibliothek (<code>ara::idsm</code>) auf.\n</li><li><strong>IPC-Transport:</strong> Die Aufrufe beider Schnittstellen (<code>EventReporter</code>, <code>ReportingModeProvider</code>) werden über Inter-Process-Communication an den daemon-basierten <code>Intrusion Detection System Manager</code> übertragen.\n</li><li><strong>Daemon-Verarbeitung:</strong> Der IdsM-Daemon verarbeitet Moduskonfigurationen und filtert/aggregiert gemeldete Security Events gemäß den aktiven Filter- und Reporting-Regeln.\n</li><li><strong>Rückmeldung:</strong> Beide Schnittstellen bestätigen die Entgegennahme der Anfragen über Standard-Rückgabetypen (<code>ara::core::Result</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API- und Manifest-Vertrag:</strong>\n<ul class=\"fig-list\"><li>Entwickler einer <code>Adaptive Application</code> müssen in den ARXML-Modellen (Application Design / Execution Manifest) Service-Ports für <code>EventReporter</code> und gegebenenfalls <code>ReportingModeProvider</code> konfigurieren und an die entsprechenden IdsM-Instanzen binden.\n</li></ul>\n</li><li><strong>Zugriffskontrolle &amp; Privilegien:</strong>\n<ul class=\"fig-list\"><li>Während das Melden von Ereignissen (<code>EventReporter</code>) typischerweise breiter gestreut für überwachte Applikationen zugänglich ist, erfordert die Modus-Steuerung (<code>SetReportingMode()</code>) restriktive Berechtigungen (z. B. Identity and Access Management / IAM), um unbefugtes Deaktivieren oder Manipulieren des IDS-Monitorings zu unterbinden.\n</li></ul>\n</li><li><strong>Architektur-Entkopplung:</strong>\n<ul class=\"fig-list\"><li>Die Aufteilung in zwei funktionale Interfaces trennt administrative Steuerungsaufgaben sauber vom kontinuierlichen Sensor-Reporting, während die daemon-basierte Architektur eine robuste, nicht-blockierende Ausführung sicherstellt.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b07d62866897deec", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Komponentendiagramm mit Schnittstellen- und Realisierungsbeziehungen, annotiert mit Stereotypen des AUTOSAR Adaptive Platform (AAP) Profils.\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP Release R24-11), Funktionsbereich <em>Intrusion Detection System</em> (IDS).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der standardisierten Schnittstellen zur Meldung sicherheitsrelevanter Ereignisse (<code>EventReporter</code>) sowie zur Steuerung und Abfrage des Reporting-Modus (<code>ReportingModeProvider</code>) zwischen einer <code>Adaptive Application</code> und dem zentralen <code>Intrusion Detection System Manager</code> (IdsM).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Adaptive Application</code></strong> (UML-Komponente):\n<ul class=\"fig-list\"><li>Repräsentiert einen Prozess im User-Space der Adaptive Platform, der als Security-Event-Sensor fungiert und über Ports auf die IdsM-Schnittstellen zugreift.\n</li></ul>\n</li><li><strong><code>«aapPortInterface,aapAPI» EventReporter</code></strong> (UML-Interface):\n<ul class=\"fig-list\"><li><strong>Stereotypen:</strong> <code>«aapPortInterface»</code>, <code>«aapAPI»</code> (C++ Programmierschnittstelle <code>ara::idsm::EventReporter</code>).\n</li><li><strong>Operationen:</strong> <code>+ ReportEvent()</code>: Öffentliche Methode zum Übermitteln von Security Events inklusive Event-ID und optionaler Kontextdaten.\n</li></ul>\n</li><li><strong><code>«aapAPI,aapPortInterface» ReportingModeProvider</code></strong> (UML-Interface):\n<ul class=\"fig-list\"><li><strong>Stereotypen:</strong> <code>«aapAPI»</code>, <code>«aapPortInterface»</code> (C++ Programmierschnittstelle <code>ara::idsm::ReportingModeProvider</code>).\n</li><li><strong>Operationen:</strong>\n<ul class=\"fig-list\"><li><code>+ GetReportingMode()</code>: Öffentliche Methode zur Abfrage des aktuellen Reporting-Modus des IdsM.\n</li><li><code>+ SetReportingMode()</code>: Öffentliche Methode zum Konfigurieren bzw. Umschalten des Reporting-Modus.\n</li></ul>\n</li></ul>\n</li><li><strong><code>«aapFunctionalCluster» Intrusion Detection System Manager</code></strong> (UML-Komponente):\n<ul class=\"fig-list\"><li><strong>Stereotyp:</strong> <code>«aapFunctionalCluster»</code>: Standardisierter Kernbestandteil der Adaptive Platform Architecture.\n</li><li><strong>Realisierungsform:</strong> <code>daemon-based</code>: Läuft als eigenständiger System-Daemon/Dienstprozess auf OS-Ebene.\n</li></ul>\n</li><li><strong>Beziehungen:</strong>\n<ul class=\"fig-list\"><li><code>Adaptive Application</code> –«use»→ <code>EventReporter</code>: Abhängigkeitsbeziehung (Client-Nutzung zum Melden von Events).\n</li><li><code>Adaptive Application</code> –«use»→ <code>ReportingModeProvider</code>: Abhängigkeitsbeziehung (Client-Nutzung zur Abfrage und Steuerung des Reporting-Modus).\n</li><li><code>Intrusion Detection System Manager</code> $\\dashrightarrow \\triangle$ <code>EventReporter</code>: Schnittstellen-Realisierung durch den IdsM-Daemon.\n</li><li><code>Intrusion Detection System Manager</code> $\\dashrightarrow \\triangle$ <code>ReportingModeProvider</code>: Schnittstellen-Realisierung durch den IdsM-Daemon.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialisierung &amp; Modusverwaltung:</strong>\n<ul class=\"fig-list\"><li>Eine autorisierte <code>Adaptive Application</code> kann über <code>GetReportingMode()</code> den aktuellen Überwachungszustand des IdsM abfragen bzw. mittels <code>SetReportingMode()</code> den aktiven Reporting-Modus steuern (z. B. Aktivierung/Deaktivierung bestimmter Reporting-Klassen).\n</li></ul>\n</li><li><strong>Security-Event-Trigger:</strong> Eine <code>Adaptive Application</code> erkennt zur Laufzeit ein sicherheitskritisches Ereignis.\n</li><li><strong>Synchroner API-Aufruf:</strong> Die Applikation ruft <code>ReportEvent()</code> der Client-Bibliothek (<code>ara::idsm</code>) auf.\n</li><li><strong>IPC-Transport:</strong> Die Aufrufe beider Schnittstellen (<code>EventReporter</code>, <code>ReportingModeProvider</code>) werden über Inter-Process-Communication an den daemon-basierten <code>Intrusion Detection System Manager</code> übertragen.\n</li><li><strong>Daemon-Verarbeitung:</strong> Der IdsM-Daemon verarbeitet Moduskonfigurationen und filtert/aggregiert gemeldete Security Events gemäß den aktiven Filter- und Reporting-Regeln.\n</li><li><strong>Rückmeldung:</strong> Beide Schnittstellen bestätigen die Entgegennahme der Anfragen über Standard-Rückgabetypen (<code>ara::core::Result</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API- und Manifest-Vertrag:</strong>\n<ul class=\"fig-list\"><li>Entwickler einer <code>Adaptive Application</code> müssen in den ARXML-Modellen (Application Design / Execution Manifest) Service-Ports für <code>EventReporter</code> und gegebenenfalls <code>ReportingModeProvider</code> konfigurieren und an die entsprechenden IdsM-Instanzen binden.\n</li></ul>\n</li><li><strong>Zugriffskontrolle &amp; Privilegien:</strong>\n<ul class=\"fig-list\"><li>Während das Melden von Ereignissen (<code>EventReporter</code>) typischerweise breiter gestreut für überwachte Applikationen zugänglich ist, erfordert die Modus-Steuerung (<code>SetReportingMode()</code>) restriktive Berechtigungen (z. B. Identity and Access Management / IAM), um unbefugtes Deaktivieren oder Manipulieren des IDS-Monitorings zu unterbinden.\n</li></ul>\n</li><li><strong>Architektur-Entkopplung:</strong>\n<ul class=\"fig-list\"><li>Die Aufteilung in zwei funktionale Interfaces trennt administrative Steuerungsaufgaben sauber vom kontinuierlichen Sensor-Reporting, während die daemon-basierte Architektur eine robuste, nicht-blockierende Ausführung sicherstellt.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ad8535477782c40f", "to": "FIG-7126de56b9fa299d", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>ReportingModeProvider</code> (Interface):</strong> Neues Interface mit den Stereotypen <code>«aapAPI,aapPortInterface»</code> und den Operationen <code>+ GetReportingMode()</code> sowie <code>+ SetReportingMode()</code> hinzugefügt.\n</li><li><strong><code>Adaptive Application</code> → <code>ReportingModeProvider</code> (Abhängigkeit):</strong> Neue <code>«use»</code>-Beziehung von der Applikation auf das Interface ergänzt.\n</li><li><strong><code>Intrusion Detection System Manager</code> $\\dashrightarrow \\triangle$ <code>ReportingModeProvider</code> (Realisierung):</strong> Neue Schnittstellen-Realisierungsbeziehung vom IdsM-Cluster auf das Interface ergänzt.\n</li><li><strong><code>Adaptive Application</code> (Komponente):</strong> Horizontale Verbreiterung der Komponente zur visuellen Abdeckung beider Schnittstellen.\n</li></ul>"}, {"from": "FIG-7126de56b9fa299d", "to": "FIG-b07d62866897deec", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
